-- 수험표 할인 모음(혜택함). 지금까지 프론트 코드(discountData.ts)에 있던 목록을 옮겨 와 어드민에서 고친다.
-- 날짜는 한국 날짜. 출처에 없으면 NULL(시작일 없음 = 이미 진행 중, 마지막 날 없음 = 끝나는 날 모름).
-- 챙길 것(bring)은 한 줄에 하나씩.
CREATE TABLE discounts (
    id BIGINT NOT NULL AUTO_INCREMENT,
    brand VARCHAR(100) NOT NULL,
    category VARCHAR(20) NOT NULL,
    benefit VARCHAR(200) NOT NULL,
    start_date DATE NULL,
    end_date DATE NULL,
    conditions VARCHAR(1000) NULL,
    area VARCHAR(20) NOT NULL,
    place VARCHAR(100) NULL,
    source_url VARCHAR(500) NOT NULL,
    source_date DATE NULL,
    highlight VARCHAR(30) NULL,
    bring VARCHAR(500) NULL,
    how_to VARCHAR(20) NULL,
    companions VARCHAR(200) NULL,
    branches VARCHAR(200) NULL,
    image_url VARCHAR(500) NULL,
    image_source VARCHAR(500) NULL,
    visible BOOLEAN NOT NULL DEFAULT TRUE,
    updated_by_name VARCHAR(50) NULL,
    created_at DATETIME(6) NOT NULL,
    updated_at DATETIME(6) NOT NULL,
    PRIMARY KEY (id)
);

